template:
@php
    $clip = is_array($file) && ! empty($file['url']) ? $file : null;
    $picture = is_array($poster) && ! empty($poster['url']) ? $poster : null;
    $shape = is_string($ratio) && trim($ratio) !== '' ? trim($ratio) : null;
@endphp
<section class="b-showcase-background b-showcase-background--{{ $width === 'narrow' ? 'narrow' : 'full' }}" data-wx-block="showcase-background">
    @if ($heading)
        <h2 class="b-showcase-background__heading">{{ $heading }}</h2>
    @endif
    @if ($note)
        <p class="b-showcase-background__note">{{ $note }}</p>
    @endif
    <div class="b-showcase-background__frame">
        @if ($clip)
            <x-webx-video variant="background" :file="$clip" :poster="$picture" :ratio="$shape" class="b-showcase-background__video">
                @if ($title)
                    <div class="b-showcase-background__screen">
                        <p class="b-showcase-background__title">{{ $title }}</p>
                        @if ($text)
                            <p class="b-showcase-background__text">{{ $text }}</p>
                        @endif
                        <a class="b-showcase-background__button" href="#showcase-background-try">What to try</a>
                    </div>
                @endif
            </x-webx-video>
        @endif
    </div>
</section>

styles:
.b-showcase-background {
    max-width: var(--site-container-width);
    margin: 0 auto;
    padding: var(--site-space-6) var(--site-gutter);
}

.b-showcase-background__heading {
    margin: 0 0 var(--site-space-2);
}

.b-showcase-background__note {
    margin: 0 0 var(--site-space-4);
    color: var(--site-color-text-muted);
}

.b-showcase-background--narrow .b-showcase-background__frame {
    max-width: 20rem;
    padding: var(--site-space-3);
    border: 1px dashed var(--site-color-border);
}

/* The first screen over the video: its own shade, so the words read on any frame of it. */
.b-showcase-background__screen {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-end;
    gap: var(--site-space-3);
    box-sizing: border-box;
    min-height: 100%;
    padding: var(--site-space-6) var(--site-space-6) calc(var(--site-space-6) + 44px);
    background: linear-gradient(to top, color-mix(in srgb, var(--site-color-text) 70%, transparent), transparent);
    color: var(--site-color-bg);
}

.b-showcase-background__title {
    margin: 0;
    font-family: var(--site-font-heading);
    font-size: var(--site-font-size-1);
    font-weight: 700;
    line-height: 1.1;
}

.b-showcase-background__text {
    max-width: 36em;
    margin: 0;
}

.b-showcase-background__button {
    display: inline-flex;
    align-items: center;
    min-height: 44px;
    padding: 0 var(--site-space-4);
    border-radius: var(--site-radius-md);
    background: var(--site-color-accent);
    color: var(--site-color-accent-contrast);
    text-decoration: none;
}

.b-showcase-background--narrow .b-showcase-background__screen {
    padding: var(--site-space-3) var(--site-space-3) calc(var(--site-space-3) + 44px);
}

.b-showcase-background--narrow .b-showcase-background__title {
    font-size: var(--site-font-size-3);
}
